// Author: Federica Sarnataro
// Description:
//   Host side of the Simply-V CSR (hw/xilinx/rtl/simplyv_csr.sv), for the Cortex-A9 #0 of the
//   Zynq-7000 PS. The PS reaches the CSR through M_AXI_GP0.
//   The host never writes STATUS, and RT_STATUS (runtime only) is not in this header.
//   The runtime side is in sw/SoC/lib/simplyv/inc/simplyv_csr.h.

#ifndef SIMPLYV_CSR_HOST_H
#define SIMPLYV_CSR_HOST_H

#include <stdint.h>
#include "ps_hw.h"  // generated by build_ps_app.py from the XSA
#include "simplyv_conf.h"

// CSR base address seen by the PS
#define CSR_HOST_BASEADDR (PS_M_AXI_GP0_BASEADDR + (uintptr_t)_peripheral_CSR_start)

// Registers used by the host (byte offsets)
#define CSR_OFF_COMMAND   (0x00u) // W: command to execute
#define CSR_OFF_STATUS    (0x04u) // R: state of Simply-V
#define CSR_OFF_BOOT_ADDR (0x08u) // RW: boot address of the CPU
#define CSR_OFF_PTR_IN    (0x0Cu) // RW: pointer to the input data (address seen by the CPU)
#define CSR_OFF_PTR_OUT   (0x10u) // RW: pointer to the output data (address seen by the CPU)

// Commands
#define CSR_CMD_RESET_CPU       (1u)
#define CSR_CMD_LOAD_PROGRAM    (2u)
#define CSR_CMD_LOAD_INPUT_DATA (3u)
#define CSR_CMD_RUN             (4u)
#define CSR_CMD_RESET_ALL       (5u)

// States (read in STATUS)
#define CSR_ST_IDLE  (0u)
#define CSR_ST_BUSY  (1u)
#define CSR_ST_DONE  (2u)
#define CSR_ST_ERROR (3u)
#define CSR_ST_HALT  (4u)

// Returned by csr_wait() when STATUS is still BUSY
#define CSR_TIMEOUT  (0xFFFFFFFFu)

// Internal: write a register (never STATUS)
static inline void csr_host_write(uint32_t offset, uint32_t value)
{
    *(volatile uint32_t *)(CSR_HOST_BASEADDR + offset) = value;
}

// Read STATUS
static inline uint32_t csr_status(void)
{
    return *(volatile uint32_t *)(CSR_HOST_BASEADDR + CSR_OFF_STATUS);
}

// RESET CPU: the CPU stops, STATUS goes to IDLE
static inline void csr_reset_cpu(void)
{
    csr_host_write(CSR_OFF_COMMAND, CSR_CMD_RESET_CPU);
}

// LOAD PROGRAM, then the boot address
static inline void csr_load_program(uint32_t boot_addr)
{
    csr_host_write(CSR_OFF_COMMAND, CSR_CMD_LOAD_PROGRAM);
    csr_host_write(CSR_OFF_BOOT_ADDR, boot_addr);
}

// LOAD INPUT DATA, then the pointers (addresses seen by the CPU)
static inline void csr_load_input_data(uint32_t ptr_in, uint32_t ptr_out)
{
    csr_host_write(CSR_OFF_COMMAND, CSR_CMD_LOAD_INPUT_DATA);
    csr_host_write(CSR_OFF_PTR_IN, ptr_in);
    csr_host_write(CSR_OFF_PTR_OUT, ptr_out);
}

// RUN: STATUS goes to BUSY, the CPU starts from the boot address
static inline void csr_run(void)
{
    csr_host_write(CSR_OFF_COMMAND, CSR_CMD_RUN);
}

// RESET ALL: the only way out of ERROR, STATUS goes to BUSY
static inline void csr_reset_all(void)
{
    csr_host_write(CSR_OFF_COMMAND, CSR_CMD_RESET_ALL);
}

// Poll STATUS until DONE or ERROR, at most max_polls reads.
// Returns the state, or CSR_TIMEOUT if STATUS is still BUSY (UC3)
static inline uint32_t csr_wait(uint32_t max_polls)
{
    uint32_t status;
    for (uint32_t i = 0; i < max_polls; i++) {
        status = csr_status();
        if ( (status == CSR_ST_DONE) || (status == CSR_ST_ERROR) ) {
            return status;
        }
    }
    return CSR_TIMEOUT;
}

#endif // SIMPLYV_CSR_HOST_H
